  "/*\n * Design tokens for @spy4x/preact-theme.\n *\n * Every colour, radius and font the preset styles against is a custom property,\n * so an app restyles the whole library by setting variables instead of forking\n * CSS. Defaults come from the products the components were extracted from:\n * purple is the primary colour.\n *\n * This file is not an importable specifier once the package is installed — JSR does not export a\n * CSS file as a module, so `@import \"@spy4x/preact-theme/tokens.css\"` resolves nowhere for a\n * consumer. `@spy4x/preact-theme`'s `README.md` → \"Install\" has the recipe that actually\n * compiles: it splices this file's text, exported as `TOKENS_CSS`, into a Tailwind build. An app\n * that keeps its own copy of this file (vendored, not installed) can still `@import` it directly,\n * with an override written after it so it wins the cascade:\n *\n *   :root {\n *     --color-primary: oklch(0.55 0.18 255);\n *   }\n *\n * These are deliberately plain custom properties and not a Tailwind `@theme`\n * block. Tailwind resolves `@theme` at build time, so a variable declared in\n * both an app's `@theme` and the library's would be folded into whichever\n * declaration the compiler saw last — the app could not win. The preset reads\n * every token through `var()`, which CSS resolves at runtime, so the cascade\n * decides.\n *\n * Light values live in `:root`, dark values in `.dark`, matching the class-based\n * `dark` variant in `preset.css`.\n */\n\n:root {\n  /* Primary — buttons, links, focus rings, active nav. --color-primary-muted is the focus ring of\n     form fields, and of `.btn` under `.dark`; an app sets --color-focus-ring to move both off it. */\n  --color-primary: oklch(0.381 0.176 304.987); /* purple-900 */\n  --color-primary-foreground: oklch(0.977 0.014 308.299); /* purple-50 */\n  --color-primary-muted: oklch(0.558 0.288 302.321); /* purple-600 */\n\n  /* Accent — the colour the components draw their fills, marks and focus rings in. Step 900 of the\n     scale below is this colour, and in the light palette it is --color-primary: setting\n     --color-primary recolours the components with it. */\n  --color-accent: var(--color-primary);\n  --color-accent-900: var(--color-accent); /* the rest of the scale is at the end of this file */\n\n  /* Surfaces — page, raised card, form control. */\n  --color-surface: oklch(1 0 0); /* white */\n  --color-canvas: oklch(0.967 0.003 264.542); /* gray-100, a step below white: cards stand off it */\n\n  /* Borders — subtle chrome, control border. */\n  --color-border-subtle: oklch(0.928 0.006 264.531); /* gray-200 */\n  --color-border-control: oklch(0.872 0.01 258.338); /* gray-300 */\n\n  /* Text — base, secondary, placeholder. */\n  --color-foreground: oklch(0.13 0.028 261.692); /* gray-950 */\n  --color-muted-foreground: oklch(0.446 0.03 256.802); /* gray-600: AA on the canvas too */\n  --color-placeholder: oklch(0.551 0.027 264.364); /* gray-500 */\n\n  /* Status — button tones, map markers, metric readouts. */\n  --color-danger: oklch(0.577 0.245 27.325); /* red-600 */\n  --color-danger-foreground: oklch(0.971 0.013 17.38); /* red-50 */\n  --color-warning: oklch(0.646 0.222 41.116); /* orange-600 */\n  --color-warning-foreground: oklch(0.98 0.016 73.684); /* orange-50 */\n  --color-success: oklch(0.527 0.154 150.069); /* green-700 */\n  --color-success-foreground: oklch(0.982 0.018 155.826); /* green-50 */\n\n  /* Geometry. */\n  --radius-primary: 0.5rem; /* rounded-lg */\n  --radius-control: 0.375rem; /* rounded-md */\n  --font-sans: \"Poppins\", ui-sans-serif, system-ui, sans-serif;\n  /* --font-serif and --font-mono are deliberately not redeclared here: Tailwind 4 already defines\n     both (see README.md → \"Theming\" → \"Fonts\"), and a `:root` declaration in this file would win\n     the cascade over an app's own `@theme --font-mono`, the same problem the header comment above\n     explains for colour tokens — an app could not override it. #257 asked for the two tokens to\n     exist, not for this package to own their default value. */\n}\n\n.dark {\n  --color-primary: oklch(0.21 0.006 285.885); /* near-black chrome, not purple */\n  /* The components keep the purple accent in dark, where --color-primary is chrome. An app that\n     recolours the dark palette sets --color-accent here, or on `:root` for both palettes. */\n  --color-accent: oklch(0.381 0.176 304.987); /* purple-900 */\n  --color-primary-foreground: oklch(0.977 0.014 308.299);\n  --color-primary-muted: oklch(0.714 0.203 305.504); /* purple-400 */\n\n  --color-surface: oklch(0.278 0.033 256.848); /* gray-800 */\n  --color-canvas: oklch(0.21 0.034 264.665); /* gray-900 */\n\n  --color-border-subtle: oklch(0.373 0.034 259.733); /* gray-700 */\n  --color-border-control: oklch(0.446 0.03 256.802); /* gray-600 */\n\n  --color-foreground: oklch(0.985 0.002 247.839); /* gray-50 */\n  --color-muted-foreground: oklch(0.707 0.022 261.325); /* gray-400 */\n  --color-placeholder: oklch(0.707 0.022 261.325); /* gray-400 */\n\n  --color-danger: oklch(0.637 0.237 25.331); /* red-500 */\n}\n\n/*\n * The accent scale — eleven steps named like Tailwind's palette, the steps the components used to\n * take from `purple-*`. `preset.css` maps each onto a Tailwind colour (`bg-accent-900`,\n * `dark:text-accent-400`, `ring-accent-900`, `bg-accent-900/30`).\n *\n * Step 900 is --color-accent itself, declared with the other tokens above. Every other step keeps the lightness of Tailwind's purple step\n * with the same number, and takes its hue and chroma from --color-accent through relative colour\n * syntax: chroma scaled by the purple step's chroma over purple-900's, hue moved by the purple\n * step's hue minus purple-900's. With no token set, --color-accent is purple-900, so every step is\n * Tailwind's own purple step to the third decimal; a grey accent gives a grey scale, a blue one a\n * blue scale. Lightness is fixed rather than relative, so a tint stays a tint whatever the accent's\n * own lightness: pick an accent about as dark as purple-900, since white text sits on it.\n *\n * Declared on `:root` only, so the scale is worked out once from the root's --color-accent and\n * inherited as colours: set --color-primary or --color-accent on `:root`, not on a subtree. A\n * browser without relative colour syntax skips this block, and `preset.css`'s fallbacks — the\n * literal purple steps — apply instead.\n */\n@supports (color: oklch(from red l c h)) {\n  :root {\n    --color-accent-50: oklch(from var(--color-accent) 0.977 calc(c * 0.014 / 0.176) calc(h + 3.312));\n    --color-accent-100: oklch(from var(--color-accent) 0.946 calc(c * 0.033 / 0.176) calc(h + 2.187));\n    --color-accent-200: oklch(from var(--color-accent) 0.902 calc(c * 0.063 / 0.176) calc(h + 1.716));\n    --color-accent-300: oklch(from var(--color-accent) 0.827 calc(c * 0.119 / 0.176) calc(h + 1.396));\n    --color-accent-400: oklch(from var(--color-accent) 0.714 calc(c * 0.203 / 0.176) calc(h + 0.517));\n    --color-accent-500: oklch(from var(--color-accent) 0.627 calc(c * 0.265 / 0.176) calc(h - 1.087));\n    --color-accent-600: oklch(from var(--color-accent) 0.558 calc(c * 0.288 / 0.176) calc(h - 2.666));\n    --color-accent-700: oklch(from var(--color-accent) 0.496 calc(c * 0.265 / 0.176) calc(h - 3.063));\n    --color-accent-800: oklch(from var(--color-accent) 0.438 calc(c * 0.218 / 0.176) calc(h - 1.263));\n    --color-accent-950: oklch(from var(--color-accent) 0.291 calc(c * 0.149 / 0.176) calc(h - 2.27));\n  }\n}\n"
